// =====================================================================
//  KIEM MA — trai tim cua tang 3 (middleware)
// ---------------------------------------------------------------------
//  Vao  : msg.payload = {"code":"E17C4D","ts":1699}  tu topic .../sequence
//  Ra 0 : lenh dieu khien gui xuong ESP32 qua .../cmd
//  Ra 1 : ban ghi 1 lan thu -> ghi log CSV + bang lich su + bieu do
//  Ra 2 : ket qua lan thu gan nhat -> hien len dashboard
// =====================================================================

const TOPIC_CMD         = "ueh/ak_majespecter/gate/cmd";
const MA_MAC_DINH       = "E17C4D";
const SO_LAN_SAI_TOI_DA = 3;   // phai khop thresholds.max_attempts
const LOCKOUT_GIAY      = 30;  // phai khop thresholds.lockout_sec
const TTL_MO_GIAY       = 5;   // phai khop thresholds.unlock_hold_sec

// Ma hop le nam trong flow context chu khong viet cung trong code, de sau nay
// doi ma luc dang chay ma khong phai sua va deploy lai flow.
let maHopLe = flow.get("ma_hop_le");
if (!maHopLe) {
    maHopLe = MA_MAC_DINH;
    flow.set("ma_hop_le", maHopLe);
}

const bayGio   = Date.now();
const maNhap   = (msg.payload && msg.payload.code ? String(msg.payload.code) : "").toUpperCase();
const thoiGian = new Date().toLocaleString("vi-VN");

// ---------------------------------------------------------------------
//  1. DANG LOCKOUT -> BO QUA hoan toan
// ---------------------------------------------------------------------
//  Khong dem, khong tra loi lenh nao. Van ghi log de biet co nguoi thu
//  trong luc dang bi khoa — day la thong tin bao mat dang gia.
const lockoutDenKhi = flow.get("lockout_den_khi") || 0;
if (bayGio < lockoutDenKhi) {
    const conLai = Math.ceil((lockoutDenKhi - bayGio) / 1000);
    node.status({ fill: "red", shape: "ring", text: "lockout con " + conLai + "s" });
    return [
        null,
        { payload: {
            thoi_gian: thoiGian, ma: maNhap,
            ket_qua: "BI CHAN (dang lockout)",
            so_lan_sai: flow.get("so_lan_sai") || 0, mau: "#ff9800"
        } },
        { payload: { chu: "BI CHAN", phu: "dang lockout, con " + conLai + "s", mau: "#9c27b0" } }
    ];
}

// ---------------------------------------------------------------------
//  2. MA DUNG -> mo khoa
// ---------------------------------------------------------------------
if (maNhap === maHopLe) {
    flow.set("so_lan_sai", 0);                                   // xoa bo dem sai
    flow.set("dem_thanh_cong", (flow.get("dem_thanh_cong") || 0) + 1);
    node.status({ fill: "green", shape: "dot", text: "dung ma -> mo khoa" });
    return [
        { topic: TOPIC_CMD, payload: { action: "unlock", ttl: TTL_MO_GIAY } },
        { payload: {
            thoi_gian: thoiGian, ma: maNhap,
            ket_qua: "DUNG — MO KHOA", so_lan_sai: 0, mau: "#4caf50"
        } },
        { payload: { chu: "MO KHOA", phu: "tu dong dong sau " + TTL_MO_GIAY + "s", mau: "#4caf50" } }
    ];
}

// ---------------------------------------------------------------------
//  3. MA SAI -> tang bo dem
// ---------------------------------------------------------------------
const soLanSai = (flow.get("so_lan_sai") || 0) + 1;
flow.set("so_lan_sai", soLanSai);
flow.set("dem_that_bai", (flow.get("dem_that_bai") || 0) + 1);

// --- Du so lan sai -> lockout ---
if (soLanSai >= SO_LAN_SAI_TOI_DA) {
    flow.set("lockout_den_khi", bayGio + LOCKOUT_GIAY * 1000);

    // Sau LOCKOUT_GIAY giay tu mo co va xoa bo dem.
    // Moc thoi gian 'lockout_den_khi' moi la can cu chinh — neu Node-RED bi
    // khoi dong lai giua chung lam mat hen gio nay thi phep so sanh o muc 1
    // van chan dung, khong bi ho.
    setTimeout(function () {
        flow.set("lockout_den_khi", 0);
        flow.set("so_lan_sai", 0);
        node.send([null, null, { payload: {
            chu: "SAN SANG", phu: "het lockout, thu lai duoc", mau: "#607d8b"
        } }]);
    }, LOCKOUT_GIAY * 1000);

    node.status({ fill: "red", shape: "dot", text: "sai " + soLanSai + " lan -> LOCKOUT" });
    return [
        { topic: TOPIC_CMD, payload: { action: "lockout", sec: LOCKOUT_GIAY } },
        { payload: {
            thoi_gian: thoiGian, ma: maNhap,
            ket_qua: "SAI LAN " + soLanSai + " — LOCKOUT " + LOCKOUT_GIAY + "s",
            so_lan_sai: soLanSai, mau: "#f44336"
        } },
        { payload: { chu: "LOCKOUT", phu: "khoa " + LOCKOUT_GIAY + " giay", mau: "#f44336" } }
    ];
}

// --- Sai nhung chua du so lan -> chi tu choi ---
node.status({ fill: "yellow", shape: "dot", text: "sai " + soLanSai + "/" + SO_LAN_SAI_TOI_DA });
return [
    { topic: TOPIC_CMD, payload: { action: "deny" } },
    { payload: {
        thoi_gian: thoiGian, ma: maNhap,
        ket_qua: "SAI (lan " + soLanSai + "/" + SO_LAN_SAI_TOI_DA + ")",
        so_lan_sai: soLanSai, mau: "#ff9800"
    } },
    { payload: { chu: "TU CHOI", phu: "sai " + soLanSai + "/" + SO_LAN_SAI_TOI_DA, mau: "#ff9800" } }
];

// =====================================================================
//  CHUAN BI 1 DONG CHO access_log.csv
// ---------------------------------------------------------------------
//  Tra ve object phang; node 'csv' phia sau se doi thanh dong CSV va tu
//  them dong tieu de o lan ghi dau tien.
//  Dung ISO 8601 cho cot timestamp de Excel va pandas deu doc duoc.
// =====================================================================
return {
    payload: {
        timestamp:            new Date().toISOString(),
        ma_nhap:              msg.payload.ma,
        ket_qua:              msg.payload.ket_qua,
        so_lan_sai_lien_tiep: msg.payload.so_lan_sai
    }
};

// =====================================================================
//  BANG 10 LAN TRUY CAP GAN NHAT
// ---------------------------------------------------------------------
//  Giu danh sach trong flow context roi day CA MANG len ui_template.
//  Ban ghi moi nhat nam tren cung.
// =====================================================================
let ds = flow.get("lich_su") || [];
ds.unshift(msg.payload);
if (ds.length > 10) {
    ds = ds.slice(0, 10);
}
flow.set("lich_su", ds);
return { payload: ds };

// =====================================================================
//  BIEU DO SO LAN THANH CONG / THAT BAI
// ---------------------------------------------------------------------
//  ui_chart dang cot phan biet cac cot bang msg.topic, nen phai gui
//  hai ban tin rieng chu khong gui mot object gop.
// =====================================================================
node.send({ topic: "Thanh cong", payload: flow.get("dem_thanh_cong") || 0 });
node.send({ topic: "That bai",   payload: flow.get("dem_that_bai")   || 0 });
return null;

// =====================================================================
//  DOC .../state DO ESP32 GUI LEN
// ---------------------------------------------------------------------
//  payload: {"lock":"open","attempts":1,"uptime":123}
//  Day la trang thai THAT cua o khoa — coi day la can cu, khong phai
//  ket qua kiem ma ben Node-RED (ket qua do hien o o widget rieng).
// =====================================================================
const p = msg.payload || {};

// Ghi lai luc nghe duoc, dung cho phan theo doi thiet bi con song.
flow.set("esp_lan_cuoi", Date.now());

let chu = "DA KHOA";
let mau = "#f44336";          // do
if (p.lock === "open")    { chu = "DA MO";   mau = "#4caf50"; }   // xanh la
if (p.lock === "lockout") { chu = "LOCKOUT"; mau = "#9c27b0"; }   // tim

return {
    payload: {
        chu: chu,
        phu: "ESP32 bao: " + p.lock + " | sai " + (p.attempts || 0)
             + " lan | uptime " + (p.uptime || 0) + "s",
        mau: mau
    }
};

// =====================================================================
//  THEO DOI ESP32 CON SONG KHONG
// ---------------------------------------------------------------------
//  Firmware publish .../state deu dan moi 5 giay. Qua 15 giay (lo 3 nhip)
//  khong nghe gi thi coi nhu mat ket noi.
//  Node inject phia truoc kich hoat ham nay moi 5 giay.
// =====================================================================
const lanCuoi = flow.get("esp_lan_cuoi") || 0;

if (!lanCuoi) {
    node.status({ fill: "grey", shape: "ring", text: "chua nghe thay ESP32" });
    return { payload: "CHUA NHAN DUOC TIN NAO TU ESP32" };
}

const giay = Math.round((Date.now() - lanCuoi) / 1000);
if (giay > 15) {
    node.status({ fill: "red", shape: "ring", text: "mat ket noi " + giay + "s" });
    return { payload: "MAT KET NOI (" + giay + "s truoc)" };
}

node.status({ fill: "green", shape: "dot", text: "online" });
return { payload: "ONLINE (nghe " + giay + "s truoc)" };

// =====================================================================
//  MO KHAN CAP TU DASHBOARD
// ---------------------------------------------------------------------
//  Day la LUONG DOWNLINK THU HAI cua he thong: dashboard (tang 4) ra lenh
//  thang xuong ESP32 (tang 1) qua .../cmd, khong di qua khau nhan dien
//  cu chi. Dung khi camera hong hoac nguoi dung khong lam duoc cu chi.
//
//  LUU Y: neu dang trong 30 giay lockout thi FIRMWARE se bo qua lenh nay
//  (day la chu y — chan ca duong vong). Phai bam "Reset lockout" truoc.
// =====================================================================
const TOPIC_CMD = "ueh/ak_majespecter/gate/cmd";

node.status({ fill: "blue", shape: "dot", text: "mo khan cap" });
return [
    { topic: TOPIC_CMD, payload: { action: "unlock", ttl: 5 } },
    { payload: {
        thoi_gian: new Date().toLocaleString("vi-VN"),
        ma: "(khan cap)", ket_qua: "MO TU DASHBOARD",
        so_lan_sai: flow.get("so_lan_sai") || 0, mau: "#2196f3"
    } }
];

// =====================================================================
//  RESET LOCKOUT
// ---------------------------------------------------------------------
//  Lockout duoc giu o HAI noi doc lap, phai xoa ca hai:
//    1. Node-RED : co 'lockout_den_khi' va bo dem 'so_lan_sai'
//    2. ESP32    : bien lockoutUntilMs trong firmware
//
//  Spec chi cho phep 3 action (unlock / deny / lockout) nen de xoa lockout
//  o ESP32 ta gui lockout voi sec = 0: firmware dat han la "ngay bay gio",
//  vong loop ke tiep thay da qua han va tu tra ve trang thai khoa binh thuong.
// =====================================================================
const TOPIC_CMD = "ueh/ak_majespecter/gate/cmd";

flow.set("lockout_den_khi", 0);
flow.set("so_lan_sai", 0);

node.status({ fill: "blue", shape: "dot", text: "da reset lockout" });
return [
    { topic: TOPIC_CMD, payload: { action: "lockout", sec: 0 } },
    { payload: { chu: "SAN SANG", phu: "da xoa lockout o ca Node-RED va ESP32", mau: "#607d8b" } }
];
